$ErrorActionPreference='Stop';Add-Type -AssemblyName UIAutomationClient,UIAutomationTypes;function Assert-Console{$p=Get-Process -Id 999999 -EA Stop;if($p.Path -ine 'C:\candidate''s folder\iMouse2.exe' -or $p.StartTime.ToUniversalTime().ToFileTimeUtc() -ne 123456789){throw 'console identity changed; no action sent'};if($p.MainWindowHandle -eq 0){throw 'console has no window'};$script:root=[System.Windows.Automation.AutomationElement]::FromHandle($p.MainWindowHandle);if($script:root.Current.ProcessId -ne 999999){throw 'wrong window process'}};Assert-Console;function Find-Id($id){$c=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty,$id);return $script:root.FindFirst([System.Windows.Automation.TreeScope]::Descendants,$c)};$title=Find-Id 'SelectedTitle';if($null -eq $title){throw 'no SelectedTitle'};$name=$title.Current.Name;if($name -notlike '*C24C*' -or $name -like '*C241*'){throw ('selected ' + $name)}; $boxes=$script:root.FindAll([System.Windows.Automation.TreeScope]::Descendants,(New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty,[System.Windows.Automation.ControlType]::CheckBox)));foreach($c in $boxes){$id=[string]$c.Current.AutomationId;$nm=[string]$c.Current.Name;if($id -eq 'BatchMode' -or $id -eq 'SelectAllBox' -or $id -like 'Mirror*' -or $nm -like 'Mirror*'){$tog=[string]$c.GetCurrentPattern([System.Windows.Automation.TogglePattern]::Pattern).Current.ToggleState;if($tog -ne 'Off'){throw ('mirror not Off: '+$id+' '+$nm+' '+$tog)}}};if($null -eq (Find-Id 'SelectAllBox')){throw 'no mirror checkbox'};Assert-Console;$settings=Find-Id 'SettingsButton';if($null -eq $settings -or -not $settings.Current.IsEnabled){throw 'Settings unavailable'};$settings.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke();$until=[DateTime]::UtcNow.AddSeconds(2);$el=$null;do{Assert-Console;$el=Find-Id 'DisconnectButton';if($null -ne $el -and $el.Current.IsEnabled -and -not $el.Current.IsOffscreen){break};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow -lt $until);if($null -eq $el -or -not $el.Current.IsEnabled -or $el.Current.IsOffscreen){throw 'Disconnect unavailable'};$title=Find-Id 'SelectedTitle';if($null -eq $title){throw 'no SelectedTitle'};$name=$title.Current.Name;if($name -notlike '*C24C*' -or $name -like '*C241*'){throw ('selected ' + $name)}; $boxes=$script:root.FindAll([System.Windows.Automation.TreeScope]::Descendants,(New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty,[System.Windows.Automation.ControlType]::CheckBox)));foreach($c in $boxes){$id=[string]$c.Current.AutomationId;$nm=[string]$c.Current.Name;if($id -eq 'BatchMode' -or $id -eq 'SelectAllBox' -or $id -like 'Mirror*' -or $nm -like 'Mirror*'){$tog=[string]$c.GetCurrentPattern([System.Windows.Automation.TogglePattern]::Pattern).Current.ToggleState;if($tog -ne 'Off'){throw ('mirror not Off: '+$id+' '+$nm+' '+$tog)}}};if($null -eq (Find-Id 'SelectAllBox')){throw 'no mirror checkbox'};Assert-Console;Write-Output ([DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds());[Console]::Out.Flush();$el.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke();$until=[DateTime]::UtcNow.AddSeconds(12);do{Assert-Console;$status=Find-Id 'ConnectionStatus';$input=Find-Id 'InputStateText';$disconnect=Find-Id 'DisconnectButton';if($null -ne $status -and $null -ne $input -and $null -ne $disconnect -and $status.Current.Name -ceq 'Disconnected' -and $input.Current.Name -ceq 'Input released' -and -not $disconnect.Current.IsEnabled){'ok';exit 0};Start-Sleep -Milliseconds 100}while([DateTime]::UtcNow -lt $until);throw 'Disconnect did not confirm input release'